mapper.select:
SELECT COUNT(*)
FROM AUTH a
         JOIN USERS u ON u.UUID = a.USER_UID
WHERE a.email = #{email}
  AND u.STATUS = 'ACTIVE'
  AND a.USER_UID != #{uuid}

SELECT COUNT(*)
FROM AUTH a
         JOIN USERS u ON u.UUID = a.USER_UID
WHERE a.phone = #{phone}
  AND u.STATUS = 'ACTIVE'
  AND a.USER_UID != #{uuid}

SELECT *
FROM auth
WHERE provider = #{provider}
  AND provider_user_id = #{providerUserId}
